// 注意：此處不加 ->where('Stop', 0) 過濾。
// 學收口徑應以「當月實際出席堂次」為事實依據；課程是否已結案（Stop=1）
// 屬後續行政動作，不應影響已發生的財務事實。
// INNER JOIN sc_counts 已確保只返回當月有出席堂次的課程，歷史課程無堂次者自動排除。
// 參考 PRD：.cursor/plans/歷史課程排除學收修正_0ff99e77.plan.md FR-001
$query = StudentClass::query()
    ->joinSub($sessionCounts, 'sc_counts', function ($join) {
        $join->on('StudentClass.ID', '=', 'sc_counts.StudentClassID');
    })
    ->with(['student', 'teacher']);

if (!empty($studentIds)) {
    $query->whereIn('StudentClass.StudentID', $studentIds);
}

$query->select('StudentClass.*', 'sc_counts.cnt as monthly_session_count');

$allRows = (clone $query)->get();

// 與 branchMonthlyTuition 一致：不過濾 Stop，讓當月有堂次的歷史課程也納入 CSV。
$query = StudentClass::query()
    ->joinSub($sessionCounts, 'sc_counts', function ($join) {
        $join->on('StudentClass.ID', '=', 'sc_counts.StudentClassID');
    })
    ->with(['student', 'teacher']);

if (!empty($studentIds)) {
    $query->whereIn('StudentClass.StudentID', $studentIds);
}

$query->select('StudentClass.*', 'sc_counts.cnt as monthly_session_count');

$allRows = $query->get();

